import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useMutation, useQueryClient } from 'react-query';
import { likePrompt, usePrompt } from '../../api/prompts';
import { useAuth } from '../../contexts/AuthContext';
import { FiHeart, FiCopy, FiEye, FiTrendingUp, FiUser, FiClock } from 'react-icons/fi';
import toast from 'react-hot-toast';

const PromptCard = ({ prompt }) => {
  const { user, isAuthenticated } = useAuth();
  const queryClient = useQueryClient();
  const [isLiked, setIsLiked] = useState(
    prompt.likes?.some(like => like._id === user?._id)
  );

  const likeMutation = useMutation(likePrompt, {
    onSuccess: (data) => {
      setIsLiked(data.isLiked);
      queryClient.invalidateQueries(['prompts']);
      toast.success(isLiked ? 'Removed from likes' : 'Added to likes');
    },
    onError: () => {
      toast.error('Failed to update like');
    },
  });

  const usePromptMutation = useMutation(usePrompt, {
    onSuccess: () => {
      queryClient.invalidateQueries(['prompts']);
      toast.success('Usage count updated');
    },
    onError: () => {
      toast.error('Failed to update usage count');
    },
  });

  const handleLike = () => {
    if (!isAuthenticated) {
      toast.error('Please login to like prompts');
      return;
    }
    likeMutation.mutate(prompt._id);
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(prompt.content);
      toast.success('Prompt copied to clipboard!');
    } catch (err) {
      toast.error('Failed to copy prompt');
    }
  };

  const handleUse = () => {
    usePromptMutation.mutate(prompt._id);
  };

  const formatDate = (dateString) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now - date);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    
    if (diffDays === 1) return '1 day ago';
    if (diffDays < 7) return `${diffDays} days ago`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)} weeks ago`;
    if (diffDays < 365) return `${Math.floor(diffDays / 30)} months ago`;
    return `${Math.floor(diffDays / 365)} years ago`;
  };

  const getCategoryColor = (category) => {
    const colors = {
      chatgpt: 'bg-green-100 text-green-800',
      midjourney: 'bg-purple-100 text-purple-800',
      dalle: 'bg-blue-100 text-blue-800',
      bard: 'bg-yellow-100 text-yellow-800',
      claude: 'bg-orange-100 text-orange-800',
      other: 'bg-gray-100 text-gray-800',
    };
    return colors[category] || colors.other;
  };

  return (
    <div className="pro-card hover:shadow-md transition-shadow duration-200">
      {/* Header */}
      <div className="flex items-start justify-between mb-4">
        <div className="flex-1">
          <Link 
            to={`/prompts/${prompt._id}`}
            className="text-lg font-semibold pro-text-primary hover:text-blue-600 transition-colors line-clamp-2"
          >
            {prompt.title}
          </Link>
          <div className="flex items-center space-x-2 mt-1">
            <Link 
              to={`/user/${prompt.author.username}`}
              className="flex items-center space-x-1 text-sm pro-text-secondary hover:text-blue-600 transition-colors"
            >
              <FiUser className="w-3 h-3" />
              <span>{prompt.author.username}</span>
            </Link>
            <span className="text-gray-400">•</span>
            <span className="flex items-center space-x-1 text-sm pro-text-muted">
              <FiClock className="w-3 h-3" />
              <span>{formatDate(prompt.createdAt)}</span>
            </span>
          </div>
        </div>
        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getCategoryColor(prompt.category)}`}>
          {prompt.category}
        </span>
      </div>

      {/* Content */}
      <div className="mb-4">
        <p className="text-gray-700 line-clamp-3 mb-3">
          {prompt.description || prompt.content}
        </p>
        {prompt.tags && prompt.tags.length > 0 && (
          <div className="flex flex-wrap gap-1">
            {prompt.tags.slice(0, 3).map((tag, index) => (
              <span key={index} className="tag">
                #{tag}
              </span>
            ))}
            {prompt.tags.length > 3 && (
              <span className="text-xs text-gray-500">+{prompt.tags.length - 3} more</span>
            )}
          </div>
        )}
      </div>

      {/* Stats */}
      <div className="flex items-center justify-between text-sm text-gray-500 mb-4">
        <div className="flex items-center space-x-4">
          <span className="flex items-center space-x-1">
            <FiEye className="w-4 h-4" />
            <span>{prompt.views}</span>
          </span>
          <span className="flex items-center space-x-1">
            <FiTrendingUp className="w-4 h-4" />
            <span>{prompt.usageCount}</span>
          </span>
          <span className="flex items-center space-x-1">
            <FiHeart className="w-4 h-4" />
            <span>{prompt.likes?.length || 0}</span>
          </span>
        </div>
      </div>

      {/* Actions */}
      <div className="flex items-center justify-between">
        <div className="flex space-x-2">
          <button
            onClick={handleCopy}
            className="flex items-center space-x-1 px-3 py-1.5 text-sm text-gray-600 hover:text-blue-600 hover:bg-blue-50 rounded-md transition-colors"
            title="Copy prompt"
          >
            <FiCopy className="w-4 h-4" />
            <span>Copy</span>
          </button>
          <button
            onClick={handleUse}
            className="flex items-center space-x-1 px-3 py-1.5 text-sm text-gray-600 hover:text-green-600 hover:bg-green-50 rounded-md transition-colors"
            title="Mark as used"
          >
            <FiTrendingUp className="w-4 h-4" />
            <span>Use</span>
          </button>
        </div>
        <button
          onClick={handleLike}
          disabled={likeMutation.isLoading}
          className={`flex items-center space-x-1 px-3 py-1.5 text-sm rounded-md transition-colors ${
            isLiked
              ? 'text-red-600 bg-red-50 hover:bg-red-100'
              : 'text-gray-600 hover:text-red-600 hover:bg-red-50'
          }`}
          title={isLiked ? 'Remove from likes' : 'Add to likes'}
        >
          <FiHeart className={`w-4 h-4 ${isLiked ? 'fill-current' : ''}`} />
          <span>{isLiked ? 'Liked' : 'Like'}</span>
        </button>
      </div>
    </div>
  );
};

export default PromptCard;
